class Bucket:
    def __init__(self, rate, cap): self.rate, self.cap, self.t, self.n = rate, cap, time.monotonic(), cap
    def take(self):
        now = time.monotonic(); self.n = min(self.cap, self.n + (now-self.t)*self.rate); self.t = now
        if self.n >= 1: self.n -= 1; return 0
        return (1-self.n)/self.rate
